typedef float rational_t;

class vector4d
{
public:
  rational_t x, y, z, w;
};

class matrix4x4
{
public:
  typedef rational_t T;

  vector4d x __attribute__((aligned(16)));
  vector4d y;
  vector4d z;
  vector4d w;

  inline matrix4x4& operator*=(T s)
  {
    x.x *= s;  x.y *= s;  x.z *= s; x.w *= s;
    y.x *= s;  y.y *= s;  y.z *= s; y.w *= s;
    z.x *= s;  z.y *= s;  z.z *= s; z.w *= s;
    w.x *= s;  w.y *= s;  w.z *= s; w.w *= s;
    return *this;
  }

  matrix4x4 inverse();
  matrix4x4 adjugate();
  T det() const;
};

extern const matrix4x4 identity_matrix;

__asm__(".equ det__C9matrix4x4, 0x001DF710");
__asm__(".equ adjugate__9matrix4x4, 0x001DF8F0");

matrix4x4 matrix4x4::inverse()
{
  rational_t det = this->det();

  if(det != 0.0f)
    return this->adjugate() *= (1.0f / det);
  else
    return identity_matrix;
}
